#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using ull = unsigned long long;
using pii = pair<int, int>;
using vi = vector<int>;
using vvi = vector<vi>;

const int INF = 1e9;
const int MOD = 1e9 + 7;

int dist[15][15][15][15];
int capacity[400][400];
char grid[20][20];
char reactions[20][20];
const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};
int iteration = 3;
int visited[400];

int N, T;

int augment(int u, int sink, int flow) {
    if (u == sink) return flow;
    if (visited[u] == iteration) return 0;
    visited[u] = iteration;
    for (int v = 0; v <= sink; ++v) {
        int pushed = 0;
        if (capacity[u][v] > 0 && (pushed = augment(v, sink, min(flow, capacity[u][v])))) {
            capacity[u][v] -= pushed;
            capacity[v][u] += pushed;
            return pushed;
        }
    }
    return 0;
}

inline int idx(int x, int y) {
    return (x - 1) * N + y - 1;
}

int reachDist[13][13];
int tempReach[13][13];

void propagate(int value) {
    memcpy(tempReach, reachDist, sizeof(reachDist));
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (tempReach[i][j] == value) {
                for (int d = 0; d < 4; ++d) {
                    int ni = i + dx[d];
                    int nj = j + dy[d];
                    if (ni >= 1 && nj >= 1 && ni <= N && nj <= N && reachDist[ni][nj] < value && grid[ni][nj] != 'Y') {
                        reachDist[ni][nj] = value;
                    }
                }
            }
        }
    }
}

bool canSpread(int sx, int sy, int tx, int ty, int infx, int infy) {
    memset(reachDist, 0, sizeof(reachDist));
    reachDist[sx][sy] = 1;
    reachDist[infx][infy] = 2;
    for (int step = 0; step < 100; ++step) {
        propagate(1);
        if (reachDist[tx][ty] == 1) return true;
        propagate(2);
        if (reachDist[tx][ty] == 2) return false;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int infx = -1, infy = -1;
    memset(dist, 0x01, sizeof(dist));
    cin >> N >> T;

    for (int i = 1; i <= N; ++i) {
        cin >> (grid[i] + 1);
        for (int j = 1; j <= N; ++j) {
            dist[i][j][i][j] = 0;
            if (grid[i][j] == 'Z') {
                infx = i;
                infy = j;
            }
        }
    }

    for (int i = 1; i <= N; ++i) {
        cin >> (reactions[i] + 1);
    }

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            for (int d = 0; d < 4; ++d) {
                int ni = i + dx[d];
                int nj = j + dy[d];
                if (ni >= 1 && nj >= 1 && ni <= N && nj <= N) {
                    if (grid[i][j] != 'Y' && grid[ni][nj] != 'Y') {
                        dist[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }

    for (int k1 = 1; k1 <= N; ++k1) {
        for (int k2 = 1; k2 <= N; ++k2) {
            for (int i = 1; i <= N; ++i) {
                for (int j = 1; j <= N; ++j) {
                    for (int u = 1; u <= N; ++u) {
                        for (int v = 1; v <= N; ++v) {
                            dist[i][j][u][v] = min(dist[i][j][u][v],
                                dist[i][j][k1][k2] + dist[k1][k2][u][v]);
                        }
                    }
                }
            }
        }
    }

    int source = N * N * 2 + 1;
    int sink = N * N * 2 + 2;

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (isdigit(grid[i][j])) {
                capacity[source][idx(i, j)] = grid[i][j] - '0';
            }
            if (isdigit(reactions[i][j])) {
                capacity[N * N + idx(i, j)][sink] = reactions[i][j] - '0';
            }

            if (isdigit(grid[i][j])) {
                for (int u = 1; u <= N; ++u) {
                    for (int v = 1; v <= N; ++v) {
                        if (grid[i][j] > '0' && reactions[u][v] > '0') {
                            if (isdigit(reactions[u][v]) && dist[i][j][u][v] <= T && canSpread(i, j, u, v, infx, infy)) {
                                capacity[idx(i, j)][N * N + idx(u, v)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }

    int maxflow = 0;
    int pushed;
    while ((pushed = augment(source, sink, 1000))) {
        maxflow += pushed;
        ++iteration;
    }

    cout << maxflow << '\n';
    return 0;
}
